const listPendingMilestones = `-- name: ListPendingMilestones :many
SELECT m.id, m.title, m.due_date, m.notes, m.owner_id, o.display_name AS owner_name, m.completed_at,
       m.created_by, c.display_name AS created_by_name, m.created_at, m.updated_at
FROM milestone m
         JOIN app_user c ON c.id = m.created_by
         LEFT JOIN app_user o ON o.id = m.owner_id
WHERE m.completed_at IS NULL
ORDER BY m.due_date, m.created_at, m.id
`

type ListPendingMilestonesRow struct {
	ID            uuid.UUID
	Title         string
	DueDate       pgtype.Date
	Notes         string
	OwnerID       *string
	OwnerName     *string
	CompletedAt   *time.Time
	CreatedBy     string
	CreatedByName string
	CreatedAt     time.Time
	UpdatedAt     time.Time
}

func (q *Queries) ListPendingMilestones(ctx context.Context) ([]ListPendingMilestonesRow, error) {
	rows, err := q.db.Query(ctx, listPendingMilestones)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListPendingMilestonesRow
	for rows.Next() {
		var i ListPendingMilestonesRow
		if err := rows.Scan(
			&i.ID,
			&i.Title,
			&i.DueDate,
			&i.Notes,
			&i.OwnerID,
			&i.OwnerName,
			&i.CompletedAt,
			&i.CreatedBy,
			&i.CreatedByName,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockActivity = `-- name: LockActivity :one
SELECT id
FROM activity
WHERE code = $1
    FOR UPDATE
`

// Bloquea la fila hasta el fin de la transacción: dos ediciones de la misma actividad van una tras otra.
func (q *Queries) LockActivity(ctx context.Context, code string) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, lockActivity, code)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}

const lockMilestone = `-- name: LockMilestone :one
SELECT id
FROM milestone
WHERE id = $1
    FOR UPDATE
`

// Bloquea la fila hasta el fin de la transacción: dos ediciones del mismo hito van una tras otra.
func (q *Queries) LockMilestone(ctx context.Context, id uuid.UUID) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, lockMilestone, id)
	var id_2 uuid.UUID
	err := row.Scan(&id_2)
	return id_2, err
}

const nextActivityCode = `-- name: NextActivityCode :one

INSERT INTO code_sequence (prefix, year, last_value)
VALUES ('ACT', $1, 1)
ON CONFLICT (prefix, year) DO UPDATE SET last_value = code_sequence.last_value + 1
RETURNING last_value
`

// Actividades (fase 6). Los operadores llegan ordenados por nombre en dos arreglos paralelos.
func (q *Queries) NextActivityCode(ctx context.Context, year int32) (int32, error) {
	row := q.db.QueryRow(ctx, nextActivityCode, year)
	var last_value int32
	err := row.Scan(&last_value)
	return last_value, err
}

